const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={back:'M15 5l-7 7 7 7',home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',layers:'M3 7l9-4 9 4-9 4z M3 12l9 4 9-4 M3 17l9 4 9-4',image:'M3 3h18v18H3z M3 16l6-6 5 5 3-3 4 4 M15 7h.01',type:'M4 4h16 M12 4v16 M8 20h8',plus:'M12 5v14 M5 12h14',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',desktop:'M3 3h18v13H3z M8 21h8 M12 16v5',tablet:'M5 2h14v20H5z M11 18h2',mobile:'M7 2h10v20H7z M11 18h2',undo:'M9 4L4 9l5 5 M4 9h9a6 6 0 0 1 6 6v4',redo:'M15 4l5 5-5 5 M20 9h-9a6 6 0 0 0-6 6v4',check:'M5 12l4 4L19 6',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 1v3 M12 20v3 M1 12h3 M20 12h3 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',more:'M5 12h.01 M12 12h.01 M19 12h.01',grip:'M9 5h.01 M15 5h.01 M9 12h.01 M15 12h.01 M9 19h.01 M15 19h.01',close:'M5 5l14 14 M19 5L5 19',trash:'M3 6h18 M6 6l1 15h10l1-15 M9 6V3h6v3',copy:'M8 8h13v13H8z M16 8V3H3v13h5',up:'M6 15l6-6 6 6',chart:'M4 20V10 M10 20V4 M16 20v-7 M22 20H2',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c6 5 6 13 0 18-6-5-6-13 0-18',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',upload:'M12 16V3 M7 8l5-5 5 5 M3 16v5h18v-5',star:'M12 3l3 6 6 1-4 5 1 6-6-3-6 3 1-6-4-5 6-1z'};
const icon = n => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.layers}"/></svg>`;
const ib=(name,action,label,extra='')=>`<button type="button" class="iconbtn" data-action="${action}" title="${label}" aria-label="${label}" ${extra}>${icon(name)}</button>`;
const btn=(text,action,cls='',name='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${name?icon(name):''}${text}</button>`;
const initial={profile:{name:'Alex Morgan',title:'Independent brand & digital designer',bio:'I partner with ambitious people to build thoughtful brands and digital experiences. Based in Copenhagen. Working everywhere.',email:'hello@alexmorgan.design',location:'Copenhagen, Denmark'},headline:'Thoughtful design.\nLasting impressions.',style:'Editorial',heroVariant:'Editorial',workVariant:'Grid',palette:'ivory',accent:'#ff5a3c',spacing:'Balanced',treatment:'Sharp',motion:'Soft',typography:'Editorial pairing',sections:[{id:'hero',type:'Hero',visible:true},{id:'work',type:'Selected Work',visible:true},{id:'about',type:'About',visible:true},{id:'contact',type:'Contact',visible:true},{id:'footer',type:'Footer',visible:true}],projects:[{id:'olive',title:'Maison Olive',type:'Branding',year:'2026',role:'Brand strategy & art direction',notes:'An independent olive oil producer, rooted in the Mediterranean. A quieter, more considered identity that celebrates the everyday ritual of good food.',cover:'assets/maison-olive.png',status:'Published',visibility:'Public',featured:true,blocks:[{id:'b1',type:'Project Intro',text:'A taste of somewhere slower. A complete identity for Maison Olive, an independent olive oil producer with a deep connection to the Mediterranean.',visible:true},{id:'b2',type:'Big Image',text:'',visible:true},{id:'b3',type:'Challenge',text:'Make a small, family-run producer feel distinctive on a crowded shelf without losing the warmth of its origins.',visible:true},{id:'b4',type:'Concept',text:'Built around the everyday ritual: generous typography, sun-warmed paper, and a palette borrowed from the grove.',visible:true}]},{id:'forma',title:'Forma Studio',type:'Branding',year:'2026',role:'Visual identity',notes:'A flexible identity for a new architecture practice. Balancing rigorous structures with a distinctly human point of view.',cover:'assets/forma-studio.png',status:'Published',visibility:'Public',featured:true,blocks:[{id:'f1',type:'Project Intro',text:'Space to think differently. A flexible visual identity for an independent architecture practice.',visible:true},{id:'f2',type:'Big Image',text:'',visible:true}]},{id:'offscript',title:'Offscript — Issue 01',type:'Other',year:'2025',role:'Editorial design',notes:'An independent publication about culture beyond the mainstream. Art direction, editorial system, and launch campaign.',cover:'assets/offscript.png',status:'Draft',visibility:'Public',featured:true,blocks:[{id:'o1',type:'Project Intro',text:'Culture, outside the lines. Editorial design and art direction for a new independent magazine.',visible:true}]}],publish:{status:'Draft',slug:'alexmorgan',seoTitle:'Alex Morgan — Brand & Digital Designer',description:'Independent brand and digital designer. Thoughtful identities and experiences for ambitious people.',language:'English',search:true,analytics:true,last:null,snapshot:null},onboarding:{role:'Graphic Designer',goal:'Get freelance clients',personality:['Editorial'],step:0,complete:false},assets:[],updated:null};
let state;try{state=JSON.parse(localStorage.getItem('sitofolio-v1'))||structuredClone(initial)}catch{state=structuredClone(initial)}
let view=location.hash.slice(1)||'editor',page='Home',selected='hero',device='desktop',leftTab='Sections',propTab='Design',projectId='olive',selectedBlock=null,history=[],future=[],saveTimer,query='',filter='All projects',showAllStyles=false,aiDraft='',activePreviewProject=null;
const app=$('#app');
function save(){state.updated=new Date().toISOString();try{localStorage.setItem('sitofolio-v1',JSON.stringify(state))}catch{toast('Storage is full. Remove a large upload and try again.');return}document.querySelectorAll('.saved').forEach(e=>e.innerHTML='Saving…');clearTimeout(saveTimer);saveTimer=setTimeout(()=>document.querySelectorAll('.saved').forEach(e=>e.innerHTML=icon('check')+' Saved locally'),400)}
function mutate(fn,rerender=true){history.push(JSON.stringify(state));if(history.length>40)history.shift();future=[];fn();save();if(rerender)render();else{document.querySelectorAll('[data-action="undo"]').forEach(b=>b.disabled=!history.length);document.querySelectorAll('[data-action="redo"]').forEach(b=>b.disabled=!future.length)}}
function undo(){if(!history.length)return;future.push(JSON.stringify(state));state=JSON.parse(history.pop());save();render()}
function redo(){if(!future.length)return;history.push(JSON.stringify(state));state=JSON.parse(future.pop());save();render()}
let toastTimer;function toast(t,canUndo=false){$('#toast').innerHTML=esc(t)+(canUndo?'<button data-action="undo">Undo</button>':'');$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function go(v){if(typeof publishedPreview!=='undefined'&&['editor','overview','projects','publish'].includes(v)){publishedPreview=false;activePreviewProject=null}view=v;location.hash=v;render();window.scrollTo(0,0)}
const logo=()=>'<img class="brand" src="assets/Artboard 4.svg" alt="Sitofolio">';
function deviceControls(){return `<div class="devices" role="group" aria-label="Preview device">${['desktop','tablet','mobile'].map(d=>ib(d,'device:'+d,d[0].toUpperCase()+d.slice(1)+' preview',`aria-pressed="${device===d}" class="${device===d?'active':''}"`).replace('class="iconbtn"',`class="iconbtn ${device===d?'active':''}"`)).join('')}</div>`}
function topbar(){return `<header class="topbar"><button class="back-brand" data-action="go:overview" aria-label="Back to dashboard">${icon('back')}${logo()}</button><span class="separator"></span><span class="crumb">${esc(state.profile.name.split(' ')[0])}’s portfolio <span class="muted">/ ${esc(page)}</span></span><div class="grow"></div><span class="saved">${icon('check')} Saved locally</span><div class="row">${ib('undo','undo','Undo',history.length?'':'disabled')}${ib('redo','redo','Redo',future.length?'':'disabled')}</div>${deviceControls()}${btn('Preview','go:preview','','eye')}${btn('Publish','go:publish','primary')}${ib('sun','theme','Toggle light and dark interface')}</header>`}
function cover(p){return `<div class="project-cover"><img src="${esc(p.cover)}" alt="${esc(p.alt||p.title+' — '+p.type+' project')}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><div class="placeholder" hidden>${esc(p.title)}</div></div>`}
function projectCard(p,action='project:'){return `<button class="project-card" data-action="${action+esc(p.id)}">${cover(p)}<div class="project-caption"><div><h3>${esc(p.title)}</h3><p>${esc(p.type)} · ${esc(p.year)}</p></div><span>↗</span></div></button>`}
function portfolio(edit=false,mini=false){const palette=state.palette==='ink'?['#111111','#f6f1e8']:['#f6f1e8','#111111'];const cls={Minimal:'minimal',Editorial:'editorial',Bold:'bold',Cinematic:'cinematic',Gallery:'gallery','Clean Professional':'clean'}[state.style];const currentSections=page==='Home'?state.sections:page==='Work'?[{id:'work',type:'Selected Work',visible:true}]:page==='About'?[{id:'about',type:'About',visible:true}]:[{id:'contact',type:'Contact',visible:true}];
return `<article class="portfolio ${device} ${cls} ${state.spacing.toLowerCase()} ${state.treatment.toLowerCase()} ${state.motion.toLowerCase()} ${state.typography==='Acumin only'?'sans':''}" style="--pf-bg:${palette[0]};--pf-text:${palette[1]};--pf-accent:${state.accent}"><nav class="pf-nav"><button class="pf-name" data-action="page:Home">${esc(state.profile.name)}<span style="color:var(--pf-accent)">®</span></button><div class="pf-links">${['Work','About','Contact'].map(p=>`<button data-action="page:${p}">${p}</button>`).join('')}</div></nav>${currentSections.filter(s=>s.visible).map(s=>{let content='';if(s.type==='Hero'){const lines=state.headline.split('\n');content=`<div class="overline">${esc(state.profile.title)}</div><h1 ${edit?'contenteditable="true" data-edit="headline" aria-label="Portfolio headline"':''}>${esc(lines[0])}${lines.length>1?'<br><i>'+esc(lines.slice(1).join(' '))+'</i>':''}</h1><div class="hero-bottom"><p ${edit?'contenteditable="true" data-edit="bio" aria-label="Short introduction"':''}>${esc(state.profile.bio)}</p><span class="availability">Available for select projects</span></div>${['Split','Visual','Centered'].includes(state.heroVariant)?`<img class="hero-image" src="${esc(state.heroImage||state.projects[0]?.cover||'assets/maison-olive.png')}" alt="${esc(state.heroImageAlt||'Featured creative work')}" ${edit?'data-action="hero-image" role="button" tabindex="0" aria-label="Replace hero image"':''}>`:''}`}
else if(s.type==='Selected Work'){content=`<div class="pf-section-heading"><h2>${page==='Work'?'The collected work.':'Selected work'}<span> (${String(state.projects.filter(p=>p.status!=='Archived'&&p.status!=='Hidden').length).padStart(2,'0')})</span></h2><span>2025 — 2026</span></div><div class="project-grid">${state.projects.filter(p=>p.status!=='Archived'&&p.status!=='Hidden'&&(page==='Work'||p.featured)).map(p=>projectCard(p,edit?'project:':'preview-project:')).join('')||'<p>Your best work goes here.</p>'}</div>`}
else if(s.type==='About'){content=`<div class="pf-section-heading"><h2>A little perspective.</h2><span>ABOUT</span></div><p ${edit?'contenteditable="true" data-edit="bio" aria-label="About biography"':''}>${esc(state.profile.bio)}</p>`}
else if(s.type==='Contact'){content=`<span class="eyebrow">HAVE SOMETHING IN MIND?</span><h2>Let’s make it <i class="editorial">matter.</i></h2><p><a href="mailto:${esc(state.profile.email)}">${esc(state.profile.email)}</a></p>`}
else if(s.type==='Footer'){return `<footer class="pf-footer"><span>© 2026 ${esc(state.profile.name)}</span><span>Made with Sitofolio</span></footer>`}
else{content=`<div class="pf-section-heading"><h2>${esc(s.type)}</h2></div><p ${edit?'contenteditable="true" data-edit="section:'+s.id+'"':''}>${esc(s.text||'Add your '+s.type.toLowerCase()+' here.')}</p>`}
const typeClass=s.type==='Hero'?'pf-hero '+({Editorial:'',Visual:'visual',Centered:'visual',Split:'split',Statement:'statement'}[state.heroVariant]):s.type==='Selected Work'?'pf-work '+state.workVariant.toLowerCase():s.type==='About'?'pf-about':'pf-contact';return `<section class="pf-section ${typeClass} ${edit?'selectable '+(selected===s.id?'selected':''):''}" ${edit?`data-section="${s.id}" tabindex="0" aria-label="Select ${s.type} section"`:''}>${edit&&selected===s.id?`<span class="selection-label">${esc(s.type)}</span>`:''}${content}</section>`}).join('')}</article>`}
function editorLeft(){return `<aside class="left-panel"><div class="panel-block"><div class="row between"><span class="eyebrow">YOUR PORTFOLIO</span><span class="badge">FREE</span></div><button class="nav-row" data-action="page-menu">${icon('home')}<b>${esc(page)}</b><span class="grow"></span>${icon('down')}</button></div><div class="panel-tabs">${['Sections','Pages'].map(t=>`<button class="${leftTab===t?'active':''}" data-action="left:${t}">${t}</button>`).join('')}</div>${leftTab==='Pages'?`<div class="panel-block">${['Home','Work','About','Contact'].map(p=>`<button class="nav-row ${page===p?'active':''}" data-action="page:${p}">${icon(p==='Home'?'home':'layers')}${p}</button>`).join('')}<button class="nav-row" data-action="go:projects">${icon('grid')}Project pages</button></div>`:`<div class="section-list" style="padding-top:14px">${state.sections.map(s=>`<div class="section-row ${selected===s.id?'active':''} ${!s.visible?'hidden-section':''}" draggable="true" data-drag-section="${s.id}"><button data-action="select:${s.id}">${icon(s.type==='Hero'?'type':s.type==='Selected Work'?'grid':'layers')}${esc(s.type)}</button>${ib('eye','toggle-section:'+s.id,s.visible?'Hide '+s.type:'Show '+s.type)}</div>`).join('')}</div><div class="panel-block">${btn('Add section','add-section','full','plus')}</div>`}<div class="panel-block"><button class="nav-row" data-action="go:projects">${icon('grid')}Projects<span class="badge">${state.projects.filter(p=>p.status!=='Archived').length}</span></button><button class="nav-row" data-action="assets">${icon('image')}Assets</button></div><div class="panel-foot"><button class="nav-row ${selected===null?'active':''}" data-action="global">${icon('settings')}Global style</button><div class="help-tip" style="padding:14px 10px 0">Your work. A little more you.</div></div></aside>`}
function field(label,id,value,type='text',hint=''){return `<label class="field"><span>${label}</span>${type==='textarea'?`<textarea data-field="${id}">${esc(value)}</textarea>`:`<input type="${type}" data-field="${id}" value="${esc(value)}">`}${hint?`<small>${hint}</small>`:''}</label>`}
function selectField(label,id,value,options){return `<label class="field"><span>${label}</span><select data-field="${id}">${options.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`}
function variants(values,current,prefix){return `<div class="variants">${values.map(v=>`<button class="variant ${current===v?'active':''}" data-action="${prefix}:${v}" aria-pressed="${current===v}"><div class="variant-sketch"><b></b><b></b><b></b></div>${v}</button>`).join('')}</div>`}
function editorRight(){let s=state.sections.find(s=>s.id===selected);return `<aside class="right-panel"><div class="prop-head"><h3>${s?esc(s.type):'Global style'}</h3>${s?ib('more','section-options','Section actions'):icon('settings')}</div><div class="panel-tabs">${['Design','Content'].map(t=>`<button class="${propTab===t?'active':''}" data-action="prop:${t}">${t}</button>`).join('')}</div>${propTab==='Content'&&s?`<div class="panel-block">${s.type==='Hero'?field('Headline','headline',state.headline,'textarea')+field('Introduction','profile.bio',state.profile.bio,'textarea'):s.type==='Selected Work'?state.projects.map(p=>`<label class="check-row"><input type="checkbox" data-feature="${p.id}" ${p.featured?'checked':''}>${esc(p.title)}</label>`).join(''):s.type==='Footer'?field('Copyright name','profile.name',state.profile.name):s.type==='Contact'?field('Email','profile.email',state.profile.email,'email'):field('Content',s.type==='About'?'profile.bio':'section.'+s.id,s.type==='About'?state.profile.bio:s.text||'','textarea')}</div>`:`${s?.type==='Hero'?`<div class="panel-block"><div class="eyebrow">LAYOUT VARIANT</div>${variants(['Editorial','Visual','Split','Statement'],state.heroVariant,'hero-variant')}<p class="help-tip" style="margin-top:12px">Curated for ${esc(state.style)}.</p></div>`:s?.type==='Selected Work'?`<div class="panel-block"><div class="eyebrow">WORK LAYOUT</div>${variants(['Grid','Stacked','Masonry','Horizontal'],state.workVariant,'work-variant')}</div>`:''}<div class="panel-block">${selectField('Style family','style',state.style,['Minimal','Editorial','Bold','Cinematic','Gallery','Clean Professional'])}${selectField('Typography','typography',state.typography,['Editorial pairing','Acumin only'])}<p class="help-tip">Acumin Variable · Instrument Serif</p></div><div class="panel-block"><div class="eyebrow">COLOR PALETTE</div><div class="swatches"><button class="swatch ${state.palette==='ivory'?'active':''}" style="background:#f6f1e8" data-action="palette:ivory" aria-label="Warm ivory portfolio"></button><button class="swatch ${state.palette==='ink'?'active':''}" style="background:#111" data-action="palette:ink" aria-label="Ink black portfolio"></button></div><div style="margin-top:18px">${field('Accent color','accent',state.accent,'color')}</div></div><div class="panel-block"><div class="eyebrow">SPACING</div><div class="segmented">${['Compact','Balanced','Spacious'].map(v=>`<button class="${state.spacing===v?'active':''}" data-action="spacing:${v}">${v}</button>`).join('')}</div></div><div class="panel-block">${selectField('Image treatment','treatment',state.treatment,['Sharp','Rounded','Framed'])}${selectField('Motion','motion',state.motion,['None','Soft'])}</div>`}<div class="panel-block"><div class="assistant-note"><div class="row"><span class="ai-dot">AI</span><strong class="small">A little help, if you need it.</strong></div><p class="help-tip" style="margin:8px 0 12px">Turn your rough notes into a story worth sharing.</p>${btn('Open project assistant','project:'+state.projects[0]?.id,'quiet full')}</div></div></aside>`}
function render(){document.body.classList.toggle('dark',localStorage.getItem('sitofolio-theme')==='dark');app.innerHTML=topbar()+`<main class="editor-shell">${editorLeft()}<div class="canvas-wrap"><div class="canvas-meta"><span>${esc(page)} <span class="muted">/ ${esc(state.style)}</span></span><span>${device==='desktop'?'Fit to canvas':device==='tablet'?'Tablet · 650':'Mobile · 375'} · 100%</span></div>${portfolio(true)}</div>${editorRight()}</main>`}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){const [action,...parts]=el.dataset.action.split(':');const v=parts.join(':');if(action==='device'){device=v;render()}else if(action==='go')go(v);else if(action==='theme'){localStorage.setItem('sitofolio-theme',document.body.classList.contains('dark')?'light':'dark');render()}else if(action==='page'){page=v;activePreviewProject=null;render()}else if(action==='left'){leftTab=v;render()}else if(action==='prop'){propTab=v;render()}else if(action==='select'){selected=v;render()}else if(action==='global'){selected=null;render()}else if(action==='undo')undo();else if(action==='redo')redo();else if(action==='toggle-section')mutate(()=>{let s=state.sections.find(s=>s.id===v);s.visible=!s.visible});else if(['hero-variant','work-variant','palette','spacing'].includes(action))mutate(()=>state[{'hero-variant':'heroVariant','work-variant':'workVariant',palette:'palette',spacing:'spacing'}[action]]=v);return}const s=e.target.closest('[data-section]');if(s&&!e.target.closest('[contenteditable]')){selected=s.dataset.section;render()}});
document.addEventListener('change',e=>{if(e.target.dataset.field&&e.target.tagName==='SELECT')updateField(e.target.dataset.field,e.target.value)});
document.addEventListener('focusout',e=>{const id=e.target.dataset.edit;if(id){mutate(()=>{if(id==='headline')state.headline=e.target.innerText.trim();else if(id==='bio')state.profile.bio=e.target.innerText.trim();else if(id.startsWith('section:'))state.sections.find(s=>s.id===id.split(':')[1]).text=e.target.innerText.trim()},false)}});
render();
